    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # The two end rows provide horizontal patterns; each isolated marker is
    # replaced by the complete pattern containing its color, aligned at marker.
    patterns=[]
    for row in (grid[0],grid[-1]):
        run=[]
        for v in row:
            if v:
                run.append(v)
            elif run:
                patterns.append(run); run=[]
        if run: patterns.append(run)
